	[TestMethod]
	public void flex_direction_alternating_with_percent()
	{
		var root = CreateNode();
		root.Style.PositionType = PositionType.Absolute;
		root.Style.Width = StyleLength.Points( 200 );
		root.Style.Height = StyleLength.Points( 300 );

		var root_child0 = CreateNode();
		root_child0.Style.FlexDirection = FlexDirection.Row;
		root_child0.Style.SetPosition( Edge.Left, StyleLength.Percent( 10 ) );
		root_child0.Style.SetPosition( Edge.Top, StyleLength.Percent( 10 ) );
		root_child0.Style.Width = StyleLength.Percent( 50 );
		root_child0.Style.Height = StyleLength.Percent( 50 );
		root.InsertChild( root_child0, 0 );
		root.CalculateLayout( float.NaN, float.NaN, Direction.LTR );

		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Left, "root.Left" );
		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Top, "root.Top" );
		AssertEq( 200, FixtureGeometry.GetRect( root, true ).Width, "root.Width" );
		AssertEq( 300, FixtureGeometry.GetRect( root, true ).Height, "root.Height" );

		AssertEq( 20, FixtureGeometry.GetRect( root_child0, true ).Left, "root_child0.Left" );
		AssertEq( 30, FixtureGeometry.GetRect( root_child0, true ).Top, "root_child0.Top" );
		AssertEq( 100, FixtureGeometry.GetRect( root_child0, true ).Width, "root_child0.Width" );
		AssertEq( 150, FixtureGeometry.GetRect( root_child0, true ).Height, "root_child0.Height" );

		root.CalculateLayout( float.NaN, float.NaN, Direction.RTL );

		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Left, "root.Left" );
		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Top, "root.Top" );
		AssertEq( 200, FixtureGeometry.GetRect( root, true ).Width, "root.Width" );
		AssertEq( 300, FixtureGeometry.GetRect( root, true ).Height, "root.Height" );

		AssertEq( 120, FixtureGeometry.GetRect( root_child0, true ).Left, "root_child0.Left" );
		AssertEq( 30, FixtureGeometry.GetRect( root_child0, true ).Top, "root_child0.Top" );
		AssertEq( 100, FixtureGeometry.GetRect( root_child0, true ).Width, "root_child0.Width" );
		AssertEq( 150, FixtureGeometry.GetRect( root_child0, true ).Height, "root_child0.Height" );
	}

